def find_minimal_edit(s_in, s_out):
    """Find the minimal change between two strings"""
    # Find first difference
    min_len = min(len(s_in), len(s_out))
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found first difference
            # Check if we're inserting or replacing
            if len(s_in) > len(s_out):
                # Delete at position i
                return (s_in[i], "", i)
            elif len(s_in) < len(s_out):
                # Insert at position i  
                return ("", s_out[i], i)
            else:
                # Replace at position i
                return (s_in[i], s_out[i], i)

    # If we get here, one string is prefix of the other
    if len(s_in) > len(s_out):
        return (s_in[min_len], "", min_len)
    elif len(s_in) < len(s_out):
        return ("", s_out[min_len], min_len)
    else:
        return ("", "", -1)  # No change

inputs = ['yvzb', 'kgha', 'ck', 'xuxfh', 'fycav']
outputs = ['dedvzzg', 'kgf', 'ck', 'xuxfz', 'fdedcav']

changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"  {idx}: '{inp}' -> '{outp}' | Change: '{old_sub}' -> '{new_sub}' at pos {pos}")

